let view='feed',status='All',community='All',saved=new Set(),followed=new Set(),zoneFollows=new Set(),prefs={method:'Platform message',contact:'',from:'08:00',until:'18:00',sightings:true,public:false};
const zones=[{name:'Johannesburg',province:'Gauteng',count:24,x:430,y:170},{name:'Durban',province:'KwaZulu-Natal',count:16,x:490,y:270},{name:'Cape Town',province:'Western Cape',count:11,x:230,y:350}];
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function setView(v){view=v;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#feed-view').hidden=!['feed','search','saved'].includes(v);$('#hotspots-view').hidden=v!=='hotspots';$('#settings-view').hidden=v!=='settings';$('#advertise-view').hidden=v!=='advertise';$('#sidebar-ad').hidden=['settings','advertise'].includes(v);$('.free-access').hidden=v==='settings';const titles={advertise:['ADVERTISING & SPONSORSHIP','Keep community access free','Explore placements that support the service without exposing private reports.'],feed:['COMMUNITY VEHICLE REPORTING','Community reports','Review vehicle descriptions, share reports and submit private sightings.'],search:['NATIONAL VEHICLE SEARCH','Search vehicle reports','Filter sample records by registration, vehicle description or area.'],saved:['MONITORING','Saved reports','Reports selected for reference during this session.'],hotspots:['AREA ACTIVITY','Hotspot zones','Review broad community zones by category and reporting period.'],settings:['REPORTER PREFERENCES','Contact & privacy','Set your preferred channel, contact hours and visibility.']};let t=titles[v];$('#view-kicker').textContent=t[0];$('#view-title').textContent=t[1];$('#view-subtitle').textContent=t[2];$('.community-cover').hidden=v!=='feed';$('.composer').hidden=v!=='feed';render();if(v==='search')$('#search').focus();history.replaceState(null,'','#'+v)}
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#profile').onclick=()=>setView('settings');
function communityRender(){$('#communities').innerHTML=['All','Gauteng','KwaZulu-Natal','Western Cape'].map(p=>`<button class="community-btn ${community===p?'selected':''}" data-community="${p}">${p==='All'?'Across South Africa':p}</button>`).join('');$$('[data-community]').forEach(b=>b.onclick=()=>{community=b.dataset.community;$('#province').value=community;$('#community-name').textContent=community==='All'?'Across South Africa':community;communityRender();setView('feed');updateFollow()})}
function updateFollow(){$('#follow').textContent=followed.has(community)?'Following community':'Follow community'}$('#follow').onclick=()=>{followed.has(community)?followed.delete(community):followed.add(community);updateFollow();toast('Demo community preference updated. Live alerts are not enabled.')};communityRender();
function reportPhoto(r){if(!r.images?.length)return '';return `<figure class="report-photo"><button data-action="gallery" data-id="${r.id}" aria-label="View images for ${esc(r.title)}"><img src="${r.images[0]}" alt="${esc(r.aiImage?'AI illustration of '+r.title:'Sample attachment for '+r.title)}" width="1200" height="800" loading="lazy" decoding="async"><span class="photo-open">View image${r.images.length>1?'s':''}</span></button><figcaption>${r.aiImage?'AI-generated illustration · not a photo of a stolen vehicle':'Sample attachment · visible within this tab only'}</figcaption></figure>`}
function feedAd(){return '<aside class="ad-slot feed-ad" aria-label="Advertisement space available"><div><div class="ad-label">ADVERTISEMENT · SPACE AVAILABLE</div><h3>Your business could appear here.</h3><p>A separate placement supporting free community access.</p></div><button data-advertise>View advertising options</button></aside>'}
function render(){const q=$('#search').value.trim().toLowerCase(),p=$('#province').value;const list=reports.filter(r=>(status==='All'||r.status===status)&&(p==='All'||r.province===p)&&(view!=='saved'||saved.has(r.id))&&[r.title,r.plate,r.area,r.province].join(' ').toLowerCase().includes(q));$('#result-count').textContent=list.length+' matching sample '+(list.length===1?'report':'reports');$('#report-metrics').innerHTML=[['Showing',list.length],['Reported stolen',list.filter(r=>r.status==='Reported').length],['Recovered',list.filter(r=>r.status==='Recovered').length]].map(([label,n])=>'<div><span>'+label+'</span><strong>'+String(n).padStart(2,'0')+'</strong><small>Sample records</small></div>').join('');$('#reports').innerHTML=list.length?list.map((r,index)=>`<article class="card"><div class="card-head"><div><span class="record-type">COMMUNITY SUBMISSION</span><div class="meta">${esc(r.area)} · ${esc(r.province)}</div></div><span class="pill ${r.status.toLowerCase()}">${r.status==='Reported'?'Reported stolen':'Recovered'}</span></div><div class="card-body"><h2>${esc(r.title)}</h2>${reportPhoto(r)}<p>${esc(r.text)}</p><dl class="vehicle-strip"><div><dt>Registration</dt><dd class="plate">${esc(r.plate)}</dd></div><div><dt>Date stolen</dt><dd>${esc(r.date)}</dd></div><div><dt>Preferred contact</dt><dd>${esc(r.method)}</dd></div></dl><div class="report-provenance"><span>${esc(r.person)}</span><span>Fictional · unverified</span></div></div><div class="card-actions"><button data-action="save" data-id="${r.id}">${saved.has(r.id)?'Saved':'Save report'}</button><button data-action="details" data-id="${r.id}">Details & comments · ${r.comments.length}</button><button data-action="share" data-id="${r.id}">Share report</button><button class="sighting" data-action="sighting" data-id="${r.id}">${r.status==='Recovered'?'View recovery':'Submit private sighting'}</button></div></article>${index===0&&list.length>1&&view==='feed'?feedAd():''}`).join(''):'<div class="empty"><h2>No matching reports</h2><p>Change the search term or selected filters.</p><button id="reset-filters">Reset filters</button></div>';$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,Number(b.dataset.id)));$$('[data-advertise]').forEach(b=>b.onclick=()=>setView('advertise'));if($('#reset-filters'))$('#reset-filters').onclick=()=>{$('#search').value='';$('#province').value='All';status='All';updateStatus();render()}}
$('#search').oninput=()=>{if(!['feed','search','saved'].includes(view))setView('search');render()};$('#province').onchange=render;function updateStatus(){$$('[data-status]').forEach(b=>b.classList.toggle('selected',b.dataset.status===status))}$$('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;updateStatus();render()});
function details(r){modal(`<span class="pill ${r.status.toLowerCase()}">${esc(r.status)} · sample</span><h2 style="margin-top:16px">${esc(r.title)}</h2>${reportPhoto(r)}<p>${esc(r.text)}</p><div class="vehicle-strip"><b>${esc(r.plate)}</b><span>${esc(r.area)}, ${esc(r.province)}</span></div><p class="muted">Reported by ${esc(r.person)}. This is a fictional community report, not police verification.</p><p><b>Preferred contact:</b> ${esc(r.method)}${r.own?` · ${esc(prefs.from)}–${esc(prefs.until)}`:''}</p>${r.own&&prefs.public&&prefs.contact?`<p>Sample public contact: ${esc(prefs.contact)}</p>`:'<p class="muted">Contact details and precise sightings are private.</p>'}<button id="detail-contact" class="primary">Contact reporter</button>${r.own?` <button id="recover">${r.status==='Recovered'?'Reopen demo report':'Mark recovered'}</button> <button id="delete-report">Delete demo report</button>`:''}<h3>Community comments</h3>${r.comments.map(c=>`<div class="comment">${esc(c)}</div>`).join('')||'<p class="muted">No comments yet.</p>'}<form id="comment-form"><label>Add a sample comment<textarea name="comment" required maxlength="400" placeholder="No personal details or accusations"></textarea></label><button>Add comment</button></form><button id="flag-report" style="margin-top:16px">Flag a report</button>`);$$('#modal [data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,Number(b.dataset.id)));$('#detail-contact').onclick=()=>sighting(r,true);$('#comment-form').onsubmit=e=>{e.preventDefault();r.comments.push(new FormData(e.target).get('comment').trim());render();details(r);toast('Sample comment added in this tab.')};$('#flag-report').onclick=()=>toast('Demo flag recorded. A live moderation service is not connected.');if(r.own){$('#recover').onclick=()=>{r.status=r.status==='Recovered'?'Reported':'Recovered';render();details(r)};$('#delete-report').onclick=()=>{modal('<h2>Delete this demo report?</h2><p>This removes your sample report from this tab.</p><button class="primary" id="confirm-delete">Delete sample report</button>');$('#confirm-delete').onclick=()=>{reports=reports.filter(x=>x.id!==r.id);saved.delete(r.id);render();$('#modal').close();toast('Sample report removed.')}}}}
function sighting(r,contact=false){modal(`<h2>${contact?'Contact reporter':'Send a private sighting'}</h2><p>${esc(r.title)} · ${esc(r.area)}</p><div class="notice">Preferred method: <b>${esc(r.method)}</b>. This demo does not send messages or reveal contact details. Use fictional information only.</div><form id="sighting-form"><label>${contact?'Sample message':'Approximate sighting area'}<input required name="area" maxlength="150"></label>${contact?'':'<label>When was it seen?<input type="datetime-local" name="when" required></label>'}<label>Details<textarea required name="details" maxlength="600" placeholder="Do not identify or accuse a person"></textarea></label><label class="check"><input type="checkbox" required> I understand this is a sample and no message will be delivered.</label><button class="primary">Preview private message</button></form>`);$('#sighting-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);modal(`<h2>Private message preview</h2><p><b>To:</b> ${esc(r.person)}</p><div class="comment">${esc(d.get('area'))}<br>${esc(d.get('when')||'')}<br>${esc(d.get('details'))}</div><p class="muted">No message was delivered. Private sightings would be visible only to authorised recipients in the live platform.</p><button id="done" class="primary">Done</button>`);$('#done').onclick=()=>$('#modal').close()}}
async function action(a,id){const r=reports.find(x=>x.id===id);if(a==='gallery'){showGallery(r);return}if(a==='save'){saved.has(id)?saved.delete(id):saved.add(id);render()}if(a==='details')details(r);if(a==='sighting')r.status==='Recovered'?details(r):sighting(r);if(a==='share'){const text=`SAMPLE ONLY — ${r.title}, ${r.plate}, ${r.area}. Fictional FindBack SA prototype report. ${location.href.split('#')[0]}#sample-${r.id}`;modal(`<h2>Share a sample report</h2><p>This card is labelled fictional so it cannot be mistaken for a real theft alert.</p><textarea id="share-text" readonly>${esc(text)}</textarea><button id="copy-share" class="primary">Copy sample report</button>`);$('#copy-share').onclick=async()=>{try{await navigator.clipboard.writeText(text);r.shares++;render();toast('Sample report copied.')}catch{$('#share-text').select();toast('Select and copy the sample text.')}}}}
function reportForm(){modal(`<h2>Report a stolen vehicle</h2><div class="notice">Prototype only. Use fictional details. No SAPS case number or identity document is requested.</div><form id="report-form"><div class="two"><label>Make<input name="make" required maxlength="40" placeholder="e.g. Toyota"></label><label>Model<input name="model" required maxlength="50" placeholder="e.g. Corolla"></label></div><div class="two"><label>Colour<input name="colour" required maxlength="30"></label><label>Sample registration<input name="plate" required maxlength="25" placeholder="DEMO 004 GP"></label></div><label>Province<select name="province">${$('#province').innerHTML.replace('<option value="All">All provinces</option>','')}</select></label><div class="two"><label>Approximate area<input name="area" required maxlength="60" placeholder="Suburb or town"></label><label>Date stolen<input name="date" type="date" required max="2026-10-09"></label></div><label>Identifying details<textarea name="details" required maxlength="800" placeholder="Vehicle features only. No names of suspects or private addresses."></textarea></label><label>Sample photos (up to 3)<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><label>Preferred contact<select name="method">${['Platform message','WhatsApp','Phone call','Email'].map(m=>`<option ${prefs.method===m?'selected':''}>${m}</option>`).join('')}</select></label><p class="muted">Contact hours and visibility are managed under Contact & privacy. New reports keep contact details private by default.</p><label class="check"><input required type="checkbox"> I am using fictional information and understand this is not a police report.</label><button class="primary">Add sample report</button></form>`);$('#report-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),files=[...e.target.photos.files];if(files.length>3||files.some(f=>f.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type))){toast('Choose up to 3 JPG, PNG or WebP files, each under 5 MB.');return}reports.unshift({id:Date.now(),person:'You (sample)',initials:'You',title:`${d.get('colour')} ${d.get('make')} ${d.get('model')}`,make:d.get('make'),model:d.get('model'),plate:d.get('plate'),area:d.get('area'),province:d.get('province'),date:d.get('date'),text:d.get('details'),status:'Reported',method:d.get('method'),comments:[],shares:0,own:true,images:files.map(f=>URL.createObjectURL(f))});$('#search').value='';$('#province').value='All';status='All';updateStatus();setView('feed');$('#modal').close();toast('Sample report added. It disappears when this page reloads.')};}$('#report-top').onclick=reportForm;$('#report-compose').onclick=reportForm;
$('#settings-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);if(d.has('public')&&(d.get('method')==='Platform message'||!d.get('contact').trim())){toast('Choose an external method and a sample contact detail before public display.');return}prefs={method:d.get('method'),contact:d.get('contact').trim(),from:d.get('from'),until:d.get('until'),sightings:d.has('sightings'),public:d.has('public')};reports.filter(r=>r.own).forEach(r=>r.method=prefs.method);toast('Demo preferences saved in this tab only.')};$('#clear-demo').onclick=()=>{reports.filter(r=>r.images).forEach(r=>r.images.forEach(URL.revokeObjectURL));location.reload()};
function renderZones(){const multiplier=$('#zone-period').value==='Last 90 days'?3:1,cat=$('#zone-category').value==='Hijacking'?.5:1;$('#map-scope').textContent='Fictional dataset · '+$('#zone-period').value.toLowerCase();const count=z=>Math.round(z.count*multiplier*cat),color=n=>n<=12?'#647e9b':n<=20?'#a16a27':'#ab413d';$('#map-pins').innerHTML=zones.map(z=>`<circle cx="${z.x}" cy="${z.y}" r="${24+Math.sqrt(count(z))*4}" fill="${color(count(z))}" opacity=".14"/><circle cx="${z.x}" cy="${z.y}" r="20" fill="${color(count(z))}" stroke="white" stroke-width="3"/><text x="${z.x}" y="${z.y+5}" text-anchor="middle" fill="white" font-size="14" font-weight="700">${count(z)}</text><text x="${z.x}" y="${z.y+68}" text-anchor="middle" fill="#243b57" font-size="15" font-weight="600">${z.name}</text>`).join('');$('#zones').innerHTML='<div class="zone-table"><table><caption class="sr-only">Fictional community zone counts and follow controls</caption><thead><tr><th scope="col">Community zone</th><th scope="col">Sample reports</th><th scope="col">Monitoring</th></tr></thead><tbody>'+zones.map(z=>`<tr><th scope="row">${z.name}<small>${z.province}</small></th><td><span class="count-tag" style="color:${color(count(z))}">${count(z)}</span></td><td><button data-zone="${z.name}">${zoneFollows.has(z.name)?'Following':'Follow zone'}</button></td></tr>`).join('')+'</tbody></table></div>';$$('[data-zone]').forEach(b=>b.onclick=()=>{zoneFollows.has(b.dataset.zone)?zoneFollows.delete(b.dataset.zone):zoneFollows.add(b.dataset.zone);renderZones();toast('Demo zone preference updated. No live alerts are sent.')})}$('#zone-category').onchange=renderZones;$('#zone-period').onchange=renderZones;renderZones();$('#saps-layer').onclick=()=>modal('<h2>SAPS statistics layer</h2><p>Official aggregate statistics are planned as a separate historical layer. No SAPS dataset has been imported.</p><p>Reuse conditions, reporting periods, data validation and map boundaries must be checked first. No individual case files or case numbers will be collected.</p><a href="https://www.saps.gov.za/services/crimestats.php" target="_blank" rel="noopener">Open SAPS published statistics</a>');
$('#privacy-info').onclick=()=>modal('<h2>About this prototype</h2><p>FindBack SA is a temporary name for an independent community reporting concept. Every seeded report, count and hotspot is fictional.</p><p>This version does not create accounts, send alerts, deliver messages or retain reports on a server. Sample entries are held only in this tab’s memory. Do not enter real personal information.</p><p>Privacy controls demonstrate the intended behaviour. They do not establish POPIA compliance. Before launch, the implementation, notices, retention, security, moderation, rights procedures and applicable legal obligations need review.</p>');
setView(['feed','search','saved','hotspots','settings','advertise'].includes(location.hash.slice(1))?location.hash.slice(1):'feed');

window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['feed','search','saved','hotspots','settings','advertise'].includes(v))setView(v)});document.querySelector('.brand').addEventListener('click',()=>setView('feed'));

function showGallery(r,index=0){modal(`<h2>Vehicle imagery</h2><p>${esc(r.title)}</p><img class="gallery-image" src="${r.images[index]}" alt="${esc(r.aiImage?'AI illustration of '+r.title:'Sample attachment for '+r.title)}"><div class="notice">${r.aiImage?'AI-generated illustration for a fictional demo report. It does not depict the actual reported vehicle.':'Sample attachment for this prototype.'}</div><div class="gallery-actions">${r.images.length>1?'<button id="image-prev">Previous</button><span>'+String(index+1)+' / '+r.images.length+'</span><button id="image-next">Next</button>':''}<button id="image-details">Report details</button></div>`);if($('#image-prev')){$('#image-prev').onclick=()=>showGallery(r,(index+r.images.length-1)%r.images.length);$('#image-next').onclick=()=>showGallery(r,(index+1)%r.images.length)}$('#image-details').onclick=()=>details(r)}
$('#advertiser-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);modal(`<h2>Advertising enquiry preview</h2><div class="notice">Preview only. No message was sent, no placement was booked and no payment was taken.</div><dl class="enquiry-details"><dt>Business</dt><dd>${esc(d.get('business'))}</dd><dt>Email</dt><dd>${esc(d.get('email'))}</dd><dt>Placement</dt><dd>${esc(d.get('placement'))}</dd><dt>Audience</dt><dd>${esc(d.get('audience'))}</dd></dl><p>${esc(d.get('message'))}</p><button id="ad-done" class="primary">Done</button>`);$('#ad-done').onclick=()=>$('#modal').close()};